//! Clusters with an escape inserted at every scalar boundary, and the exact results.

/// One cluster text, a width and the exact result of every column operation.
pub struct ClusterCase {
    /// Source text.
    pub text: &'static str,
    /// Width passed to every operation.
    pub width: usize,
    /// Wrapped lines.
    pub wrapped: &'static [&'static str],
    /// Truncation without an ellipsis.
    pub truncated: &'static str,
    /// Non-strict slice from column zero.
    pub slice: (&'static str, usize),
    /// Strict slice from column zero.
    pub strict_slice: (&'static str, usize),
    /// Segments with the overlay at the width, one column long, strict after.
    pub segments: (&'static str, usize, &'static str, usize),
}

